/* Gastos Gerais — Compras + Obras & Reformas (origem: sistema-de-auditoria).
   Acrescenta ao módulo Auditoria de Compras o botão "🏗️ Gastos Gerais (Compras + Obras)": uma tela que junta os
   pedidos de compra (já carregados no módulo) com as despesas do módulo Obras & Reformas, lidas ao vivo do banco
   (view obras_despesas_pagamento, status lançado, sem recusadas) com o login do Portal.
   Mostra total geral, por loja (a loja da obra vinculada), por tipo de despesa (mão de obra, combustível,
   alimentação, materiais...), loja × tipo, mês a mês e a lista completa; Imprimir/PDF e Excel.
   Não altera o módulo publicado nem o Relatório Geral existente. Para tirar: remova a linha do
   gastos-gerais-patch.js no index.html. */
(function(){
  var CSSB="", HTMLB="", JSB="";
  function dec(x){ var s=atob(x),u=new Uint8Array(s.length); for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i); return new TextDecoder('utf-8').decode(u); }
  function ehCompras(d){
    try{
      if(!d||!d.body)return false;
      var t=(d.title||'')+' '+((d.querySelector('h1')||{}).textContent||'');
      return /RELAT[ÓO]RIO DE COMPRAS/i.test(t) || !!(d.getElementById('fForn')&&d.getElementById('fCat')&&d.getElementById('kpiGrid'));
    }catch(e){ return false; }
  }
  function injetar(d){
    if(d.getElementById('gg-patch-js'))return;
    var st=d.createElement('style'); st.id='gg-patch-css'; st.textContent=dec(CSSB); (d.head||d.body).appendChild(st);
    var box=d.createElement('div'); box.innerHTML=dec(HTMLB); while(box.firstChild)d.body.appendChild(box.firstChild);
    var sc=d.createElement('script'); sc.id='gg-patch-js'; sc.textContent=dec(JSB); d.body.appendChild(sc);
    window.__GASTOS_GERAIS_INJETADO=(window.__GASTOS_GERAIS_INJETADO||0)+1;
  }
  function varrer(doc,nivel){
    var fs=doc.querySelectorAll('iframe');
    for(var i=0;i<fs.length;i++){
      var d=null; try{ d=fs[i].contentDocument; }catch(e){}
      if(!d||d.readyState!=='complete')continue;
      if(ehCompras(d)){ try{ injetar(d); }catch(e){ console.warn('[Gastos Gerais] injeção falhou:',e); } }
      else if(nivel<3){ varrer(d,nivel+1); }
    }
  }
  window.__GASTOS_GERAIS_VERSAO='20261106-7';
  setInterval(function(){ try{ varrer(document,0); }catch(e){} },1200);
})();
